# Look for solid rectangular blocks of 8 or 5
def blocks(a, color):
    m=(a==color)
    # find maximal runs per row
    runs=[]
    for r in range(30):
        c=0
        while c<30:
            if m[r,c]:
                s=c
                while c<30 and m[r,c]: c+=1
                if c-s>=3: runs.append((r,s,c-1))
            else: c+=1
    return runs
r8=blocks(a,8)
# vertical extent
for (r,s,e) in r8:
    h=1
    while r+h<30 and all(a[r+h,c]==8 for c in range(s,e+1)):
        h+=1
    if h>=3 and e-s>=3:
        print('8-block rows',r,r+h-1,'cols',s,e)
